// Yahoo Finance APIレスポンスからデータを抽出
const chart = $json?.chart?.result?.[0];
const meta = chart?.meta || {};
const indicators = chart?.indicators?.quote?.[0] || {};
const timestamps = chart?.timestamp || [];

// 直近の取引データ
const lastIndex = timestamps.length - 1;
const prevIndex = lastIndex > 0 ? lastIndex - 1 : 0;

const currentPrice = meta.regularMarketPrice || indicators.close?.[lastIndex] || 0;
const previousClose = indicators.close?.[prevIndex] || meta.chartPreviousClose || 0;
const dailyChange = previousClose > 0 ? ((currentPrice - previousClose) / previousClose * 100).toFixed(2) : 'N/A';

// 1ヶ月間の高値・安値
const highs = (indicators.high || []).filter(v => v !== null);
const lows = (indicators.low || []).filter(v => v !== null);
const volumes = (indicators.volume || []).filter(v => v !== null);

const monthHigh = highs.length > 0 ? Math.max(...highs).toFixed(2) : 'N/A';
const monthLow = lows.length > 0 ? Math.min(...lows).toFixed(2) : 'N/A';
const avgVolume = volumes.length > 0 ? Math.round(volumes.reduce((a, b) => a + b, 0) / volumes.length) : 'N/A';

// 入力データ(銘柄情報)を保持
const inputItem = $('バッチ処理 (5件ずつ)').item;

return {
  json: {
    symbol: inputItem.json.symbol,
    name: inputItem.json.name,
    market: inputItem.json.market,
    category: inputItem.json.category,
    currentPrice: currentPrice,
    currency: meta.currency || 'USD',
    dailyChange: dailyChange,
    monthHigh: monthHigh,
    monthLow: monthLow,
    avgVolume: avgVolume,
    exchange: meta.exchangeName || 'N/A',
    fetchedAt: new Date().toISOString()
  }
};

// 全銘柄のデータを集約
const items = $input.all();

const usStocks = [];
const jpStocks = [];

for (const item of items) {
  const d = item.json;
  const entry = `${d.name} (${d.symbol}): ${d.currentPrice} ${d.currency} [日次変動: ${d.dailyChange}%] [月間高値: ${d.monthHigh} / 安値: ${d.monthLow}] [平均出来高: ${d.avgVolume?.toLocaleString() || 'N/A'}] [カテゴリ: ${d.category}]`;

  if (d.market === 'US') {
    usStocks.push(entry);
  } else {
    jpStocks.push(entry);
  }
}

const today = new Date().toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' });

const report = `=== 半導体株データレポート (${today}) ===\n\n` +
  `【米国半導体株】\n${usStocks.join('\n')}\n\n` +
  `【日本半導体株】\n${jpStocks.join('\n')}`;

return [{
  json: {
    report: report,
    date: new Date().toISOString(),
    stockCount: items.length,
    rawData: items.map(i => i.json)
  }
}];

// Claude APIのレスポンスからNotionページ用のデータを構築
const claudeResponse = $input.all()[0].json;
const analysisText = claudeResponse?.content?.[0]?.text || 'Claude分析の取得に失敗しました';
const aggregatedData = $('全銘柄データ集約').first().json;

const today = new Date();
const dateStr = today.toISOString().split('T')[0];
const titleStr = `半導体株レポート ${today.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric' })}`;

// 分析テキストをセクションに分割
const sections = analysisText.split(/\n(?=【)/);

// セクター全体のトレンドを判定
let trend = '横ばい';
if (analysisText.includes('上昇') && analysisText.indexOf('上昇') < 500) trend = '上昇';
else if (analysisText.includes('下降') && analysisText.indexOf('下降') < 500) trend = '下降';

// Notionのブロックを構築（2000文字制限対応）
function splitTextToBlocks(text, maxLen = 1900) {
  const blocks = [];
  let remaining = text;
  while (remaining.length > 0) {
    let chunk = remaining.substring(0, maxLen);
    // 改行位置で分割
    if (remaining.length > maxLen) {
      const lastNewline = chunk.lastIndexOf('\n');
      if (lastNewline > maxLen * 0.5) {
        chunk = remaining.substring(0, lastNewline);
      }
    }
    blocks.push({
      object: 'block',
      type: 'paragraph',
      paragraph: {
        rich_text: [{ type: 'text', text: { content: chunk } }]
      }
    });
    remaining = remaining.substring(chunk.length).replace(/^\n/, '');
  }
  return blocks;
}

// 個別銘柄サマリーテーブル用のデータ
const rawData = aggregatedData.rawData || [];
let stockTable = '| 銘柄 | ティッカー | 現在値 | 日次変動 | 月間高値 | 月間安値 | カテゴリ |\n';
stockTable += '|---|---|---|---|---|---|---|\n';
for (const s of rawData) {
  stockTable += `| ${s.name} | ${s.symbol} | ${s.currentPrice} ${s.currency} | ${s.dailyChange}% | ${s.monthHigh} | ${s.monthLow} | ${s.category} |\n`;
}

const notionDatabaseId = $env.NOTION_DATABASE_ID || 'YOUR_DATABASE_ID';

// Notionページ作成用のペイロード
const notionPayload = {
  parent: {
    database_id: notionDatabaseId
  },
  icon: {
    type: 'emoji',
    emoji: '📊'
  },
  properties: {
    'タイトル': {
      title: [
        { text: { content: titleStr } }
      ]
    },
    '日付': {
      date: {
        start: dateStr
      }
    },
    '市場トレンド': {
      select: {
        name: trend
      }
    },
    '銘柄数': {
      number: aggregatedData.stockCount || 0
    }
  },
  children: [
    {
      object: 'block',
      type: 'heading_1',
      heading_1: {
        rich_text: [{ type: 'text', text: { content: titleStr } }]
      }
    },
    {
      object: 'block',
      type: 'callout',
      callout: {
        icon: { type: 'emoji', emoji: '🤖' },
        rich_text: [{ type: 'text', text: { content: 'このレポートはn8n + Claude APIによって自動生成されています。' } }]
      }
    },
    {
      object: 'block',
      type: 'divider',
      divider: {}
    },
    ...splitTextToBlocks(analysisText),
    {
      object: 'block',
      type: 'divider',
      divider: {}
    },
    {
      object: 'block',
      type: 'heading_2',
      heading_2: {
        rich_text: [{ type: 'text', text: { content: '個別銘柄データ一覧' } }]
      }
    },
    {
      object: 'block',
      type: 'paragraph',
      paragraph: {
        rich_text: [{ type: 'text', text: { content: stockTable.substring(0, 1900) } }]
      }
    },
    ...(stockTable.length > 1900 ? [{
      object: 'block',
      type: 'paragraph',
      paragraph: {
        rich_text: [{ type: 'text', text: { content: stockTable.substring(1900, 3800) } }]
      }
    }] : [])
  ]
};

return [{ json: notionPayload }];

const notionResponse = $input.all()[0].json;
const pageId = notionResponse.id || 'unknown';
const pageUrl = notionResponse.url || 'unknown';

console.log(`Notionページが作成されました: ${pageUrl}`);

return [{
  json: {
    status: 'success',
    notionPageId: pageId,
    notionPageUrl: pageUrl,
    completedAt: new Date().toISOString()
  }
}];
